    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Extend the diagonal through each 6 across the grid.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                for rr in range(h):
                    cc = c + rr - r
                    if 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = 6

    # Connect collinear 1s along their diagonal.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for slope in (-1, 1):
        lines = {}
        for r, c in ones:
