def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join 1s that lie on the same diagonal.
    lines = {}
    for r, c in ones:
        for slope in (-1, 1):
            lines.setdefault((slope, c - slope * r), []).append(r)
    for (slope, intercept), rows in lines.items():
        if len(rows) < 2:
            continue
        lo, hi = min(rows), max(rows)
        for r in range(lo, hi + 1):
            c = slope * r + intercept
            if 0 <= c < w and out[r][c] == bg:
                out[r][c] = 1

        # A 6 on the joined 1 diagonal extends along the other diagonal.
        for r, c in sixes:
            if c == slope * r + intercept and lo <= r <= hi:
                for rr in range(h):
                    cc = c - slope * (rr - r)
                    if 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = 6

    return out
